     6	import java.math.BigDecimal;
     7	import java.text.DecimalFormat;
     8	import java.text.DecimalFormatSymbols;
     9	import java.util.Collections;
    10	import java.util.List;
    11	import java.util.Locale;
    12	
    13	public class FinanceNotificationHandler implements NotificationHandler {
    14	    private static final String EMAIL = "financeiro@pousadamarealta.com.br";
    15	    private long messageIdCounter = 1;
    16	
    17	    @Override
    18	    public List<NotificationMessage> handle(ReservationEvent event) {
    19	        if (event instanceof ReservationConfirmedEvent confirmed) {
    20	            return List.of(createPaymentEmail(confirmed.reservation()));
    21	        } else if (event instanceof ReservationCancelledEvent cancelled) {
    22	            if (cancelled.previousStatus() == ReservationStatus.CONFIRMED &&
    23	                cancelled.reservation().getRefund() != null &&
    24	                cancelled.reservation().getRefund().compareTo(BigDecimal.ZERO) > 0) {
    25	                return List.of(createRefundEmail(cancelled.reservation()));
    26	            }
    27	        }
    28	        return Collections.emptyList();
    29	    }
    30	
    31	    private NotificationMessage createPaymentEmail(Reservation reservation) {
    32	        String subject = "Pagamento recebido - reserva " + reservation.getId();
    33	        String body = String.format(
    34	            "Pagamento recebido.\nReserva: %d\nValor: %s",
    35	            reservation.getId(),
    36	            formatMoney(reservation.getAmountPaid())
    37	        );
    38	
    39	        return new NotificationMessage(messageIdCounter++, "EMAIL", EMAIL, subject, body);
    40	    }
    41	
    42	    private NotificationMessage createRefundEmail(Reservation reservation) {
    43	        String subject = "Reembolso - reserva " + reservation.getId();
    44	        String body = String.format(
    45	            "Reembolso necessário.\nReserva: %d\nValor: %s",
    46	            reservation.getId(),
    47	            formatMoney(reservation.getRefund())
    48	        );
    49	
    50	        return new NotificationMessage(messageIdCounter++, "EMAIL", EMAIL, subject, body);
    51	    }
    52	
    53	    private String formatMoney(BigDecimal amount) {
    54	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(new Locale("pt", "BR"));
    55	        symbols.setDecimalSeparator(',');
    56	        symbols.setGroupingSeparator('.');
    57	        DecimalFormat format = new DecimalFormat("#,##0.00", symbols);
    58	        return "R$ " + format.format(amount);
    59	    }
    60	
    61	    public void setMessageIdCounter(long counter) {
    62	        this.messageIdCounter = counter;
    63	    }
    64	}
