    13	public class GuestNotificationHandler implements NotificationHandler {
    14	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    15	    private long messageIdCounter = 1;
    16	
    17	    @Override
    18	    public List<NotificationMessage> handle(ReservationEvent event) {
    19	        if (event instanceof ReservationConfirmedEvent confirmed) {
    20	            return List.of(createConfirmationEmail(confirmed.reservation()));
    21	        }
    22	        return Collections.emptyList();
    23	    }
    24	
    25	    private NotificationMessage createConfirmationEmail(Reservation reservation) {
    26	        String subject = "Reserva confirmada - Pousada Maré Alta";
    27	        String receipt = formatReceipt(reservation);
    28	        String body = String.format("""
    29	            Olá, %s!
    30	
    31	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
    32	
    33	            %s
    34	
    35	            A entrada é a partir das 14h, e a saída, até as 12h.
    36	            Até breve!""", reservation.getGuestName(), receipt);
    37	
    38	        return new NotificationMessage(
    39	            messageIdCounter++,
    40	            "EMAIL",
    41	            reservation.getGuestEmail(),
    42	            subject,
    43	            body
    44	        );
    45	    }
    46	
    47	    private String formatReceipt(Reservation reservation) {
    48	        StringBuilder receipt = new StringBuilder();
    49	        receipt.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    50	        receipt.append("Hóspede: ").append(reservation.getGuestName())
    51	               .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
    52	        receipt.append("Quarto: ").append(reservation.getRoomNumber())
    53	               .append(" (").append(reservation.getRoomType()).append(")\n");
    54	        receipt.append("Entrada: ").append(DATE_FORMAT.format(reservation.getCheckIn()))
    55	               .append(" | Saída: ").append(DATE_FORMAT.format(reservation.getCheckOut()))
    56	               .append(" | ").append(reservation.getNights())
    57	               .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
    58	        receipt.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
    59	
    60	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    61	            receipt.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
    62	        }
    63	
    64	        receipt.append("Total: ").append(formatMoney(reservation.getTotal()));
    65	
    66	        return receipt.toString();
    67	    }
    68	
    69	    private String formatCpf(String cpf) {
    70	        if (cpf.length() == 11) {
    71	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    72	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
    73	        }
    74	        return cpf;
    75	    }
    76	
    77	    private String formatMoney(BigDecimal amount) {
    78	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(new Locale("pt", "BR"));
    79	        symbols.setDecimalSeparator(',');
    80	        symbols.setGroupingSeparator('.');
    81	        DecimalFormat format = new DecimalFormat("#,##0.00", symbols);
    82	        return "R$ " + format.format(amount);
    83	    }
    84	
    85	    public void setMessageIdCounter(long counter) {
    86	        this.messageIdCounter = counter;
    87	    }
    88	}
