     3	import com.pousadamarealta.notification.*;
     4	
     5	import java.util.ArrayList;
     6	import java.util.List;
     7	
     8	public class NotificationService {
     9	    private final List<NotificationHandler> handlers = new ArrayList<>();
    10	    private final List<NotificationMessage> sentMessages = new ArrayList<>();
    11	    private long messageIdCounter = 1;
    12	
    13	    public NotificationService() {
    14	        GuestNotificationHandler guestHandler = new GuestNotificationHandler();
    15	        HousekeepingNotificationHandler housekeepingHandler = new HousekeepingNotificationHandler();
    16	        FinanceNotificationHandler financeHandler = new FinanceNotificationHandler();
    17	
    18	        handlers.add(guestHandler);
    19	        handlers.add(housekeepingHandler);
    20	        handlers.add(financeHandler);
    21	    }
    22	
    23	    public void notify(ReservationEvent event) {
    24	        for (NotificationHandler handler : handlers) {
    25	            List<NotificationMessage> messages = handler.handle(event);
    26	            for (NotificationMessage message : messages) {
    27	                NotificationMessage numbered = new NotificationMessage(
    28	                    messageIdCounter++,
    29	                    message.getChannel(),
    30	                    message.getTo(),
    31	                    message.getSubject(),
    32	                    message.getBody()
    33	                );
    34	                sentMessages.add(numbered);
    35	            }
    36	        }
    37	    }
    38	
    39	    public List<NotificationMessage> getSentMessages() {
    40	        return List.copyOf(sentMessages);
    41	    }
    42	}
