     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.domain.*;
     4	import com.pousadamarealta.notification.ReservationCancelledEvent;
     5	import com.pousadamarealta.notification.ReservationConfirmedEvent;
     6	
     7	import java.time.LocalDate;
     8	import java.util.*;
     9	
    10	public class ReservationService {
    11	    private final RoomService roomService;
    12	    private final NotificationService notificationService;
    13	    private final Map<Long, Reservation> reservations = new HashMap<>();
    14	    private long reservationIdCounter = 1;
    15	
    16	    public ReservationService(RoomService roomService, NotificationService notificationService) {
    17	        this.roomService = roomService;
    18	        this.notificationService = notificationService;
    19	    }
    20	
    21	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    22	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    23	                                        int guests, RatePlan ratePlan) {
    24	        Room room = roomService.getRoomByNumber(roomNumber)
    25	            .orElseThrow(() -> new RoomNotFoundException(roomNumber));
    26	
    27	        if (guests > room.getCapacity()) {
    28	            throw new CapacityExceededException();
    29	        }
    30	
    31	        if (guests < 1) {
    32	            throw new InvalidRequestException("At least one guest is required");
    33	        }
    34	
    35	        if (!checkOut.isAfter(checkIn)) {
    36	            throw new InvalidRequestException("Check-out must be after check-in");
    37	        }
    38	
    39	        if (!isRoomAvailable(roomNumber, checkIn, checkOut)) {
    40	            throw new RoomUnavailableException();
    41	        }
    42	
    43	        Reservation reservation = new Reservation(
    44	            reservationIdCounter++,
    45	            roomNumber,
    46	            room.getType(),
    47	            guestName,
    48	            guestEmail,
    49	            guestCpf,
    50	            checkIn,
    51	            checkOut,
    52	            guests,
    53	            ratePlan
    54	        );
    55	
    56	        reservations.put(reservation.getId(), reservation);
    57	        return reservation;
    58	    }
    59	
    60	    private boolean isRoomAvailable(String roomNumber, LocalDate checkIn, LocalDate checkOut) {
    61	        return reservations.values().stream()
    62	            .filter(r -> r.getRoomNumber().equals(roomNumber))
    63	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
    64	            .noneMatch(r -> overlaps(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
    65	    }
    66	
    67	    private boolean overlaps(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
    68	        return start1.isBefore(end2) && start2.isBefore(end1);
    69	    }
    70	
    71	    public Optional<Reservation> getReservation(long id) {
    72	        return Optional.ofNullable(reservations.get(id));
    73	    }
    74	
    75	    public Reservation confirmReservation(long id) {
    76	        Reservation reservation = getReservation(id)
    77	            .orElseThrow(() -> new ReservationNotFoundException(id));
    78	
    79	        try {
    80	            reservation.confirm();
    81	            notificationService.notify(new ReservationConfirmedEvent(reservation));
    82	            return reservation;
    83	        } catch (IllegalStateException e) {
    84	            throw new OperationNotAllowedException(e.getMessage());
    85	        }
    86	    }
    87	
    88	    public Reservation checkInReservation(long id) {
    89	        Reservation reservation = getReservation(id)
    90	            .orElseThrow(() -> new ReservationNotFoundException(id));
    91	
    92	        try {
    93	            reservation.checkIn();
    94	            return reservation;
    95	        } catch (IllegalStateException e) {
    96	            throw new OperationNotAllowedException(e.getMessage());
    97	        }
    98	    }
    99	
   100	    public Reservation checkOutReservation(long id) {
   101	        Reservation reservation = getReservation(id)
   102	            .orElseThrow(() -> new ReservationNotFoundException(id));
   103	
   104	        try {
   105	            reservation.checkOut();
   106	            return reservation;
   107	        } catch (IllegalStateException e) {
   108	            throw new OperationNotAllowedException(e.getMessage());
   109	        }
   110	    }
   111	
   112	    public Reservation cancelReservation(long id) {
   113	        Reservation reservation = getReservation(id)
   114	            .orElseThrow(() -> new ReservationNotFoundException(id));
   115	
   116	        ReservationStatus previousStatus = reservation.getStatus();
   117	
   118	        try {
   119	            reservation.cancel();
   120	            notificationService.notify(new ReservationCancelledEvent(reservation, previousStatus));
   121	            return reservation;
   122	        } catch (IllegalStateException e) {
   123	            throw new OperationNotAllowedException(e.getMessage());
   124	        }
   125	    }
   126	
   127	    public List<Reservation> getAllReservations() {
   128	        return List.copyOf(reservations.values());
   129	    }
   130	}
