     8	public class NotificationService {
     9	    private final List<NotificationHandler> handlers = new ArrayList<>();
    10	    private final List<NotificationMessage> sentMessages = new ArrayList<>();
    11	    private long messageIdCounter = 1;
    12	
    13	    public NotificationService() {
    14	        GuestNotificationHandler guestHandler = new GuestNotificationHandler();
    15	        HousekeepingNotificationHandler housekeepingHandler = new HousekeepingNotificationHandler();
    16	        FinanceNotificationHandler financeHandler = new FinanceNotificationHandler();
    17	
    18	        handlers.add(guestHandler);
    19	        handlers.add(housekeepingHandler);
