    23	    public void notify(ReservationEvent event) {
    24	        for (NotificationHandler handler : handlers) {
    25	            List<NotificationMessage> messages = handler.handle(event);
    26	            for (NotificationMessage message : messages) {
    27	                NotificationMessage numbered = new NotificationMessage(
    28	                    messageIdCounter++,
    29	                    message.getChannel(),
    30	                    message.getTo(),
    31	                    message.getSubject(),
    32	                    message.getBody()
    33	                );
    34	                sentMessages.add(numbered);
    35	            }
    36	        }
    37	    }
    38	
    39	    public List<NotificationMessage> getSentMessages() {
    40	        return List.copyOf(sentMessages);
    41	    }
    42	}
