    12	import java.util.List;
    13	import java.util.stream.Collectors;
    14	
    15	public class ReportService {
    16	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    17	
    18	    private final RoomService roomService;
    19	    private final ReservationService reservationService;
    20	
    21	    public ReportService(RoomService roomService, ReservationService reservationService) {
    22	        this.roomService = roomService;
    23	        this.reservationService = reservationService;
    24	    }
    25	
    26	    public String generateOccupancyReport(LocalDate date) {
    27	        StringBuilder csv = new StringBuilder();
    28	        csv.append("room,type,reservation,check_in,check_out\n");
    29	
    30	        List<Reservation> occupiedReservations = reservationService.getAllReservations().stream()
    31	            .filter(r -> r.getStatus() != ReservationStatus.PENDING &&
    32	                        r.getStatus() != ReservationStatus.CANCELLED)
    33	            .filter(r -> r.occupiesNight(date))
    34	            .sorted(Comparator.comparing(Reservation::getRoomNumber))
    35	            .toList();
    36	
    37	        for (Reservation reservation : occupiedReservations) {
    38	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber()).orElseThrow();
    39	            csv.append(reservation.getRoomNumber()).append(",")
    40	               .append(room.getType()).append(",")
    41	               .append(reservation.getId()).append(",")
    42	               .append(DATE_FORMAT.format(reservation.getCheckIn())).append(",")
    43	               .append(DATE_FORMAT.format(reservation.getCheckOut())).append("\n");
    44	        }
    45	
    46	        int totalRooms = roomService.getAllRooms().size();
    47	        csv.append("total,").append(occupiedReservations.size()).append("/").append(totalRooms);
    48	
    49	        return csv.toString();
    50	    }
    51	
    52	    public String generateRevenueReport(YearMonth month) {
    53	        StringBuilder csv = new StringBuilder();
    54	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    55	
    56	        LocalDate monthStart = month.atDay(1);
    57	        LocalDate monthEnd = month.atEndOfMonth();
    58	
    59	        List<Reservation> monthReservations = reservationService.getAllReservations().stream()
    60	            .filter(r -> !r.getCheckIn().isBefore(monthStart) && !r.getCheckIn().isAfter(monthEnd))
    61	            .filter(r -> {
    62	                BigDecimal revenue = r.getAmountPaid();
    63	                if (r.getRefund() != null) {
    64	                    revenue = revenue.subtract(r.getRefund());
    65	                }
    66	                return revenue.compareTo(BigDecimal.ZERO) > 0;
    67	            })
    68	            .sorted(Comparator.comparing(Reservation::getCheckIn)
    69	                             .thenComparing(Reservation::getId))
    70	            .toList();
    71	
    72	        BigDecimal total = BigDecimal.ZERO;
    73	
    74	        for (Reservation reservation : monthReservations) {
    75	            BigDecimal amount = reservation.getAmountPaid();
    76	            if (reservation.getRefund() != null) {
    77	                amount = amount.subtract(reservation.getRefund());
    78	            }
    79	            total = total.add(amount);
    80	
    81	            csv.append(reservation.getId()).append(",")
    82	               .append(reservation.getRoomNumber()).append(",")
    83	               .append(DATE_FORMAT.format(reservation.getCheckIn())).append(",")
    84	               .append(DATE_FORMAT.format(reservation.getCheckOut())).append(",")
    85	               .append(reservation.getStatus()).append(",")
    86	               .append(formatAmount(amount)).append("\n");
    87	        }
    88	
    89	        csv.append("total,").append(formatAmount(total));
    90	
    91	        return csv.toString();
    92	    }
    93	
    94	    private String formatAmount(BigDecimal amount) {
    95	        return amount.toString();
    96	    }
    97	}
